/* ---------------------------------------------------------------- 实心图标（`V-96`，你自己给的）
   这三颗是 Iconfont 那套（**1024 网格、实心填充**），和上面 lucide 那族（24 网格、描边）
   不是一路；所以单开一张表：各自带 `viewBox`，颜色用 `fill=currentColor` 跟着主题走。
     moss-history  带时针的循环箭头  —— 快照卡上的「恢复」（有时间感：回到那一次的版本）
     moss-folder-out 文件夹 + 进箭头 —— 「导出」（导出到某个文件夹）
     moss-camera   相机（带加号）    —— 「创建快照」（快照 = 拍一张） */
const SOLID = {
// `s` = 视觉缩放（1024 格里的"看起来多大"，治"这颗比旁边大/小"）；`line` = 按**描边**画，
//   和 lucide 那族一路（不然实心块夹在描边图标里明显重一档）。
"moss-history":    {vb: "0 0 1024 1024", s: 0.86, body: BODY_HISTORY},
"moss-folder-out": {vb: "0 0 1024 1024", s: 0.72, body: BODY_FOLDER},
"moss-camera":     {vb: "0 0 1024 1024", s: 0.86, body: BODY_CAMERA},
};

function ico(name, cls) {
  const s = SOLID[name];
  if (s){
    // 先按 `s` 缩放、再挪回中心（不然是"从左下角缩"，图标会跑偏）
    const g = '<g transform="translate(512 512) scale(' + (s.s || 1) + ') translate(-512 -512)"' +
              ' fill="' + (s.line ? 'none' : 'currentColor') + '"' +
              (s.line ? ' stroke="currentColor" stroke-width="64" stroke-linejoin="round"' +
                        ' stroke-linecap="round"' : '') + '>' + s.body + '</g>';
    return '<svg class="' + (cls || 'i') + '" viewBox="' + s.vb + '" aria-hidden="true">' +
           g + '</svg>';
  }
  const body = LUCIDE[name] || LUCIDE['file'] || '';
  return '<svg class="' + (cls || 'i') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + body + '</svg>';
}
